#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeNativeLibrary: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = NativeLibrary

    public static func lift(_ handle: UInt64) throws -> NativeLibrary {
        return NativeLibrary(unsafeFromHandle: handle)
    }

    public static func lower(_ value: NativeLibrary) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> NativeLibrary {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: NativeLibrary, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNativeLibrary_lift(_ handle: UInt64) throws -> NativeLibrary {
    return try FfiConverterTypeNativeLibrary.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNativeLibrary_lower(_ value: NativeLibrary) -> UInt64 {
    return FfiConverterTypeNativeLibrary.lower(value)
}






/**
 * Single-use fresh get ceremony, bound to a session revision and a new credential.
 */
public protocol PrfActionProtocol: AnyObject, Sendable {
    
    /**
     * Fresh unpadded base64url get challenge.
     */
    func challenge()  -> String
    
    /**
     * Complete new credential descriptor; restrict get to exactly this credential.
     */
    func descriptor()  -> Data
    
    /**
     * Exact prf.eval.first input.
     */
    func salt()  -> Data
    
}
/**
 * Single-use fresh get ceremony, bound to a session revision and a new credential.
 */
open class PrfAction: PrfActionProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_colophon_ffi_fn_clone_prfaction(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_colophon_ffi_fn_free_prfaction(handle, $0) }
    }

    

    
    /**
     * Fresh unpadded base64url get challenge.
